  const usage=unique((current.usage||[]).filter(row=>row?.phrase),row=>JSON.stringify(row)),vocab=current.vocabulary||[],notes=Array.isArray(current.notesVocabularyExtensions)?current.notesVocabularyExtensions.filter(v=>v?.word&&v.meaning):[];
