 function questions(){const bank=window.StudyKnowledge?.bank;if(current&&bank?.hasLesson(current.id)){const rows=practice.mode==='vocabulary'?bank.questionsForLesson(current.id).filter(q=>q.type==='vocabulary'):bank.quizForLesson(current.id);return (practice.mode==='grammar'?rows.filter(q=>q.type==='grammar'):rows).filter(q=>!practice.onlyConcepts||practice.onlyConcepts.includes(q.conceptId));} let result=(current.quiz||[]).map(q=>({...q}));if(practice.mode==='grammar')return result.filter(q=>q.type!=='vocabulary');if(practice.mode==='vocabulary'){const vocab=current.vocabulary||[];result=result.filter(q=>q.type==='vocabulary');if(vocab.length>=2)result.push(...vocab.map((v,i)=>{const options=[v.meaning,...vocab.filter((_,j)=>j!==i).slice(0,3).map(x=>x.meaning)];const answer=i%options.length;[options[0],options[answer]]=[options[answer],options[0]];return{question:`“${v.word}” 在本课中的意思是？`,options,answer,type:'vocabulary',explanation:`${v.word}：${v.meaning}。${v.example||''}`};}));}return result;}
 function pilotFeedback(q,i){
  if(!hasReviewedFeedback(current)||!window.StudyRemediation||practice.answers[i]===q.answer)return '';
  const d=StudyRemediation.describe(q,practice.answers[i],{lesson:current}),follow=d.followUp,chosen=practice.followups?.[i];
  if(!d.rule)return '<aside class="practice-remediation"><h4>本题解析</h4><p>'+E(q.explanation||'本题解析正在整理。')+'</p><p class="small-note">这道专项题暂未配置已核对的新情境补救题。可切换到本课12题单元训练，逐题练习并订正。</p></aside>';
  return '<aside class="practice-remediation"><h4>为什么答错</h4><p><strong>规则：</strong>'+E(d.rule)+'</p><p><strong>原因：</strong>'+E(d.reason)+'</p>'+d.contrastExamples.map(e=>'<blockquote><p class="english">'+E(e.en)+'</p>'+(e.zh?'<p>'+E(e.zh)+'</p>':'')+'<small>'+E(e.sourceLabel)+'</small></blockquote>').join('')+'<button class="button subtle" data-knowledge-lesson="'+E(d.sourceLesson?.id||current.id)+'" data-practice-knowledge="'+E(q.conceptId)+'">查看对应讲解</button>'+(follow?'<section class="practice-followup"><h4>同知识点，再试一题</h4><p class="small-note">自编订正题 · 不计通关成绩</p><p>'+E(follow.question)+'</p><div class="answer-options">'+follow.options.map((o,j)=>'<button class="answer-option '+(chosen===j?'selected ':'')+(chosen!==undefined?(j===follow.answer?'correct':chosen===j?'incorrect':''):'')+'" data-followup="'+i+'" data-followup-answer="'+j+'" '+(chosen!==undefined?'disabled':'')+'><span>'+String.fromCharCode(65+j)+'</span>'+E(o)+(chosen!==undefined&&j===follow.answer?' · ✓ 正确':chosen===j?' · ✕ 答错':'')+'</button>').join('')+'</div>'+(chosen!==undefined?'<p role="status">'+(chosen===follow.answer?'✓ 订正正确':'✕ 答错 · 正确答案：'+E(follow.options[follow.answer]))+'</p><p>'+E(StudyRemediation.describe(follow,chosen,{lesson:current}).reason)+'</p>':'')+'</section>':'<p class="small-note">'+E(d.followUpMessage)+'</p>')+'</aside>';
 }
