 function openResources(){const library=window.STUDY_LIBRARY||[];openDialog('教材与学习资料',`<p class="usage-note">选择官方资源，或导入已有的课文和音频，和站内练习一起学习。</p>${library.length?`<h3>已接入的教材资料</h3><button class="button" id="open-library">前往我的教材资料</button><div class="record-list">${library.map(f=>window.StudySourceFiles?.isArchived?.(f.url)?`<div class="resource-link">${icon('file')}<span>${E(f.title)}<small>第 ${f.book} 册 · 文字版 · 原PDF已归档</small></span></div>`:`<a class="resource-link" href="${E(f.url)}" target="_blank" rel="noopener">${icon('file')}<span>${E(f.title)}<small>第 ${f.book} 册 · ${E(f.kind||'PDF')}</small></span>${icon('external')}</a>`).join('')}</div>`:''}<section class="usage-card"><h3>外研社 · 新概念英语智慧版</h3><p>出版社说明：智慧版正版图书激活后，可在“外研 U 学”获取配套数字学习资源，包括跟读单词、单词练习与课文听读。</p><a class="button" href="https://www.fltrp.com/ebook/jcjyyjzx/2023_jcjyjxzy/files/basic-html/page62.html" target="_blank" rel="noopener">查看官方资源说明${icon('external')}</a></section><section class="usage-card"><h3>语法与词汇配套学习</h3><p>外研社介绍了《新概念英语词汇在用》《新概念英语语法在用》等配套学习产品，可结合四册课程复习。</p><a class="resource-link" href="https://www.fltrp.com/c/2025-09-26/539371.shtml" target="_blank" rel="noopener">查看出版社介绍${icon('external')}</a></section><p class="small-note">资料核对：2026-10-24。外部资源的可用性及激活要求以出版社为准。本站为独立学习工具；当前文字内容来自已接入的新概念课堂笔记与练习，并非完整四册教材课文。内置音频为 Microsoft Zira 美式合成音频；导入课文可使用设备语音或自有音频。</p>`,`<button class="button primary" id="resources-import">${icon('upload')}导入我的资料</button>`);}
 function openBackupRestore(){openDialog('恢复学习备份','<p>选择此前导出的学习备份 JSON 文件。下一步会预览内容，确认前不会修改本设备记录。</p><label class="form-field">学习备份文件<input id="restore-backup-file" type="file" accept=".json,application/json"></label><p id="restore-backup-error" class="result-explanation hidden" role="alert"></p>','<button class="button" id="close-dialog">取消</button><button class="button primary" id="preview-restore-backup">预览备份</button>');}
 async function previewRestoreBackup(){const button=$('#preview-restore-backup'),error=$('#restore-backup-error');button.disabled=true;try{const file=$('#restore-backup-file').files?.[0];if(!file)throw new Error('请选择学习备份文件。');let raw;try{raw=JSON.parse(await file.text());}catch(_){throw new Error('文件不是有效的 JSON 学习备份。');}if(!button.isConnected)return;showBackupPreview(raw);}catch(problem){if(error.isConnected){error.textContent=problem.message||'无法读取备份，请检查文件。';error.classList.remove('hidden');}}finally{if(button.isConnected)button.disabled=false;}}
 function openImport(){openDialog('导入课文与音频',`<p class="small-note">把自己的资料放进学习室。导入的课文和音频只保存在当前浏览器。</p><div class="form-grid"><label class="form-field">所属分册<select id="import-book">${BOOKS.map(b=>`<option value="${b.n}" ${b.n===selectedBook?'selected':''}>${b.name} · ${b.full}</option>`).join('')}</select></label><label class="form-field">课号<input id="import-number" type="number" min="1" max="999" value="1"></label></div><label class="form-field">课文标题<input id="import-title" placeholder="如：Lesson 1 · 我的课文" maxlength="150"></label><label class="form-field">选择课文文件（TXT / LRC / JSON）<input id="import-text-file" type="file" accept=".txt,.lrc,.json"></label><label class="form-field">或粘贴英文课文<textarea id="import-text" rows="5" placeholder="每行一个段落；LRC 时间标签会自动识别。"></textarea></label><label class="form-field">配套音频（可选，单文件不超过 50MB）<input id="import-audio" type="file" accept="audio/*,.mp3,.m4a,.wav,.ogg"></label><label class="check-label"><input type="checkbox" id="audio-only">仅把音频绑定到当前课文</label><p class="small-note">JSON 支持批量课文、翻译、词汇、习惯用法和题库。学习数据备份也可从这里恢复。批量导入时请单独为各课绑定音频。</p><button class="resource-link" id="download-template">下载 JSON 资料模板${icon('download')}</button><p class="result-explanation hidden" id="import-error" role="alert"></p>`,`<button class="button" id="cancel-import">取消</button><button class="button primary" id="confirm-import">${icon('upload')}导入并开始学习</button>`);}
